<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>@yield('title','MEETA')</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet"><style>
:root{--brown:#974700;--ink:#261f1b;--paper:#fff9f5;--line:#ead4c7;--muted:#75665e}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}a{text-decoration:none;color:inherit}button,input,select,textarea{font:inherit}.wrap{max-width:1220px;margin:auto;padding-left:26px;padding-right:26px}header{height:80px;border-bottom:1px solid var(--line);background:#fffaf7;position:sticky;top:0;z-index:30}.nav{height:100%;display:flex;align-items:center;gap:28px}.logo{font-size:20px;letter-spacing:.35em;margin-right:auto}.logo small{display:block;font-size:6px;color:var(--muted)}.links{display:flex;gap:25px;font-size:14px}.nav-search{border:1px solid var(--line);border-radius:10px;padding:10px 14px}.icons{display:flex;gap:15px;align-items:center}.icon{font-size:21px}.cart-link{display:flex;align-items:center;gap:7px;position:relative}.cart-link svg{width:21px;height:21px}.cart-count{min-width:18px;height:18px;display:none;place-items:center;position:absolute;left:14px;top:-11px;border-radius:20px;background:var(--brown);color:#fff;font-size:10px;padding:0 5px}.nav-label{font-size:13px}.btn{border:1px solid var(--brown);background:transparent;color:var(--brown);padding:14px 24px;cursor:pointer}.btn.primary{background:var(--brown);color:#fff}.btn:disabled{opacity:.45;cursor:not-allowed}.toast{display:none;position:fixed;right:22px;bottom:22px;background:#2d211b;color:#fff;padding:14px 20px;border-radius:9px;z-index:100}.auth-overlay{display:none;position:fixed;inset:0;background:rgba(30,22,18,.55);z-index:200;place-items:center;padding:20px}.auth-overlay.open{display:grid}.auth-dialog{width:min(430px,100%);background:var(--paper);border:1px solid var(--line);padding:34px;text-align:center;box-shadow:0 22px 70px rgba(0,0,0,.2)}.auth-dialog h2{font:600 29px 'Playfair Display',serif;margin:0 0 12px}.auth-dialog p{color:var(--muted);line-height:1.6}.auth-dialog-actions{display:flex;gap:10px;justify-content:center;margin-top:24px}.loading{padding:100px;text-align:center;color:var(--muted)}footer{background:#eee4de;margin-top:70px}.footer{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:40px;padding-top:45px;padding-bottom:45px}.footer h4{margin-top:0}.footer p,.footer a{font-size:13px;color:var(--muted);line-height:2;display:block}@media(max-width:800px){.links,.nav-search{display:none}.footer{grid-template-columns:1fr 1fr}}@media(max-width:560px){header{height:68px}.wrap{padding-left:16px;padding-right:16px}.footer{grid-template-columns:1fr}.account-label,.cart-label{display:none}.auth-dialog-actions{flex-direction:column}}
</style>@stack('styles')</head><body><header><nav class="nav wrap"><a class="logo" href="/">MEETA<small>HOME DECOR HUB</small></a><div class="links"><a href="/">Home</a><a href="/categories">Categories</a><a href="#">By State</a><a href="#">Artisans</a><a href="#">Collections</a><a href="#">Offers</a></div><input class="nav-search" placeholder="Search crafts…" onkeydown="if(event.key==='Enter')location.href='/shop?search='+encodeURIComponent(this.value)"><div class="icons"><a class="icon" href="/wishlist" id="wishLink" data-auth-link aria-label="Wishlist">♡</a><a class="cart-link" href="/cart" data-auth-link aria-label="Shopping cart"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 4h2l2.1 10.1a2 2 0 0 0 2 1.6h7.8a2 2 0 0 0 2-1.6L20.4 7H6"/><circle cx="9" cy="20" r="1"/><circle cx="17" cy="20" r="1"/></svg><span class="cart-label nav-label">Cart</span><span id="cartCount" class="cart-count">0</span></a><a href="/login" id="accountLink"><span class="account-label nav-label">Sign in</span></a></div></nav></header>@yield('content')<footer><div class="footer wrap"><div><div class="logo">MEETA<small>HOME DECOR HUB</small></div><p>Preserving Bharat's living craft traditions through thoughtful, ethical commerce.</p></div><div><h4>Our World</h4><a href="#">Our Story</a><a href="#">Artisan Directory</a><a href="#">Sustainability</a></div><div><h4>Care & Service</h4><a href="#">Shipping & Returns</a><a href="#">Privacy Policy</a><a href="#">Contact Us</a></div><div><h4>For Artisans</h4><a href="/vendor/register">Become an Artisan</a><a href="/vendor/login">Vendor Sign In</a></div></div></footer><div id="toast" class="toast"></div><div id="authOverlay" class="auth-overlay" role="dialog" aria-modal="true" aria-labelledby="authTitle"><div class="auth-dialog"><h2 id="authTitle">Sign in to continue</h2><p>Create your personal collection, save favourites and securely manage your orders.</p><div class="auth-dialog-actions"><button class="btn" id="authCancel" type="button">Keep browsing</button><a class="btn primary" id="authLogin" href="/login">Sign in</a></div><p>New to MEETA? <a id="authRegister" href="/register" style="color:var(--brown);text-decoration:underline">Create an account</a></p></div></div><script>
const token=localStorage.getItem('meeta_token');const authHeaders={'Accept':'application/json','Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})};
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.style.display='block';setTimeout(()=>el.style.display='none',2600)}
function intendedUrl(){return location.pathname+location.search}
function loginUrl(){return '/login?redirect='+encodeURIComponent(intendedUrl())}
function redirectToLogin(){location.href=loginUrl()}
function requireAuth(){if(token)return true;if(['/cart','/checkout','/wishlist','/orders','/account'].some(path=>location.pathname===path||location.pathname.startsWith(path+'/'))){redirectToLogin();return false}const overlay=document.getElementById('authOverlay');document.getElementById('authLogin').href=loginUrl();document.getElementById('authRegister').href='/register?redirect='+encodeURIComponent(intendedUrl());overlay.classList.add('open');return false}
function protectPage(){if(!token){redirectToLogin();return false}return true}
async function api(url,options={}){const response=await fetch(url,{...options,headers:{...authHeaders,...(options.headers||{})}});if(response.status===401||response.status===419){localStorage.removeItem('meeta_token');localStorage.removeItem('meeta_user');redirectToLogin();throw Error('Your session has expired. Please sign in again.')}const json=await response.json();if(!response.ok)throw Error(json.message||Object.values(json.errors||{})[0]?.[0]||'Request failed');return json}
function setCartCount(count){const badge=document.getElementById('cartCount');badge.textContent=count;badge.style.display=count>0?'grid':'none'}
async function refreshCartCount(){if(!token)return;try{const response=await fetch('/api/customer/cart',{headers:authHeaders});if(response.status===401||response.status===419){localStorage.removeItem('meeta_token');localStorage.removeItem('meeta_user');return}if(response.ok)setCartCount((await response.json()).data.items_count||0)}catch(error){}}
if(token){document.getElementById('accountLink').innerHTML='<span class="account-label nav-label">Orders</span>';document.getElementById('accountLink').href='/orders';refreshCartCount()}
document.getElementById('authCancel').onclick=()=>document.getElementById('authOverlay').classList.remove('open');document.getElementById('authOverlay').onclick=e=>{if(e.target.id==='authOverlay')e.currentTarget.classList.remove('open')};document.querySelectorAll('[data-auth-link]').forEach(link=>link.addEventListener('click',e=>{if(!token){e.preventDefault();requireAuth()}}));
</script>@stack('scripts')</body></html>
